        public override void GlobalSetup()
        {
            var opts = new GarnetServerOptions
            {
                QuietMode = true,
                DisablePubSub = false,
                EnableVectorSetPreview = true,
            };

            server = new EmbeddedRespServer(opts, null, new GarnetServerEmbedded());
            server.Start();

            session = server.GetRespSession();

            SetupOperation(ref delCmd, DEL);
            SetupOperation(ref initCmd, INIT);
            SetupOperation(ref vaddBatchCmd, VADD_BATCH);

        }

        [IterationSetup]
        public void IterationSetup()
        {
            // Make sure we're starting from scratch each iteration
            Send(delCmd);

            // Initial VADD will be slow for initialization reasons, so do it out of the benchmark
            Send(initCmd);
        }

        [Benchmark]
        public void VADD()
        {
            Send(vaddBatchCmd);
        }
    }
